import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.CrXGS008.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),r={name:"getting-started.md"};function o(i,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>This page takes you from the purchase to the first time you open the settings panel in game. It is the same for every Nayretis script.</p><h2 id="buy-and-download" tabindex="-1">Buy and download <a class="header-anchor" href="#buy-and-download" aria-label="Permalink to &quot;Buy and download&quot;">​</a></h2><ol><li>Buy the script on the <a href="https://www.nayretis.com" target="_blank" rel="noreferrer">Nayretis store</a>. Checkout is handled by Tebex.</li><li>Log in to <a href="https://portal.cfx.re" target="_blank" rel="noreferrer">Portal</a> with the Cfx.re account you used at checkout. The script and <code>nay_lib</code> are in your granted assets.</li><li>Download both. <code>nay_lib</code> comes with every Nayretis script and is never sold on its own.</li></ol><p>The scripts are protected by Cfx escrow: they only start on a server whose license key belongs to the Cfx.re account that owns them.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li><a href="https://github.com/overextended/oxmysql" target="_blank" rel="noreferrer">oxmysql</a>, started and connected to your database.</li><li>One of the supported frameworks: ESX Legacy, QBCore, QBox or ox_core. See <a href="/bridge/">Bridge</a> for inventories, targets and notifications.</li></ul><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Copy the <code>nay_lib</code> folder and the script folder into your <code>resources</code> folder. In <code>server.cfg</code>, start them after your framework, inventory and target resources:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span># your framework, inventory and target resources here</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_car_wash</span></span></code></pre></div><p><code>nay_lib</code> is installed once, whatever the number of Nayretis scripts you run. Keep it before every Nayretis script.</p><h2 id="first-start" tabindex="-1">First start <a class="header-anchor" href="#first-start" aria-label="Permalink to &quot;First start&quot;">​</a></h2><p>Start the server. The database tables are created automatically, there is no SQL file to import. In the console you should see:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[script:nay_lib] [INFO] Bridge ready: framework=qbox inventory=ox_inventory</span></span>
<span class="line"><span>[script:nay_lib] [INFO] Ready: settings, permissions and migrations loaded</span></span></code></pre></div><p>The framework and inventory names match what your server runs.</p><h2 id="give-yourself-access" tabindex="-1">Give yourself access <a class="header-anchor" href="#give-yourself-access" aria-label="Permalink to &quot;Give yourself access&quot;">​</a></h2><p>Settings are edited in game with <code>/nay</code>. Give the admin group full access in <code>server.cfg</code>:</p><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_ace group.admin nay.admin allow</span></span></code></pre></div><p>Or grant one player from the server console:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nay_grant license &lt;license&gt; nay.admin</span></span></code></pre></div><p>Then join the server and type <code>/nay</code>. More options on the <a href="/nay-lib/permissions">Permissions</a> page.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Learn the <a href="/nay-lib/panel">/nay panel</a>: languages, theme, permissions, API and webhooks.</li><li>Set up <a href="/car-wash/">Car Wash</a>.</li><li>Something does not start? Read the <a href="/faq">FAQ</a>.</li></ul>`,23)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
